pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 amount, uint256 warpTo) public {
        amount = bound(amount, 0, address(c).balance / 10 ether > 10 ? 10 ether * 10 : type(uint256).max);
        vm.assume(amount == 10 ether);
        vm.warp(warpTo);
        address sender = address(0x1234);
        vm.deal(sender, amount);
        vm.prank(sender);
        (bool ok, ) = address(c).call{value: amount}("");
        if (ok) {
            assertEq(c.pastBlockTime(), block.timestamp);
        }
    }
}
